class LFUCache {
    int cap, minFreq;
    unordered_map<int, pair<int, int>> keyInfo;
    unordered_map<int, list<int>> freqList;
    unordered_map<int, list<int>::iterator> keyIter;

    void touch(int key) {
        int freq = keyInfo[key].second;
        freqList[freq].erase(keyIter[key]);
        keyInfo[key].second = freq + 1;
        freqList[freq + 1].push_front(key);
        keyIter[key] = freqList[freq + 1].begin();
        if (freqList[minFreq].empty()) minFreq++;
    }

public:
    LFUCache(int capacity) : cap(capacity), minFreq(0) {}

    int get(int key) {
        if (!keyInfo.count(key)) return -1;
        touch(key);
        return keyInfo[key].first;
    }

    void put(int key, int value) {
        if (cap == 0) return;
        if (keyInfo.count(key)) {
            keyInfo[key].first = value;
            touch(key);
            return;
        }
        if ((int)keyInfo.size() >= cap) {
            int evictKey = freqList[minFreq].back();
            freqList[minFreq].pop_back();
            keyInfo.erase(evictKey);
            keyIter.erase(evictKey);
        }
        keyInfo[key] = {value, 1};
        freqList[1].push_front(key);
        keyIter[key] = freqList[1].begin();
        minFreq = 1;
    }
};
